function create(kind,x,y){ const isCard=kind==='card',isTile=kind==='tile',isEnemy=['enemy','elite','boss'].includes(kind);const o={id:ID(),kind:isCard?'card':isTile?'tile':'sprite',role:isCard?'card':isTile?'tile':kind,label:isCard?'Card':kind[0].toUpperCase()+kind.slice(1),x:round(x),y:round(y),w:isTile?80:90,h:isTile?42:160,rotation:0,z:state.objects.length+1,locked:false,hidden:false,group:null,anchor:'bottom-center',padding:8,margin:0,autoSize:!isTile,lockAspect:isCard,scale:1,displayState:'base',side:isEnemy?'enemy':'player'};autoSize(o);return o;}
