function seed(){state=defaults();for(let side of ['player','enemy'])for(let i=0;i<4;i++){const o=create(side,0,0);o.label=(side==='player'?'Ally ':'Enemy ')+(i+1);state.objects.push(o)}for(let i=0;i<5;i++){const o=create('card',0,0);o.label=['Strike','Guard','Lunge','Focus','Spell'][i];if(i===2)o.displayState='selected';state.objects.push(o)}const enemy=state.objects.find(o=>o.side==='enemy');if(enemy)enemy.displayState='selected';state.cards.pageIndex=2;autoArrange();}
