function control(path,label,value,min,max,step=1,unit=''){const p=safe(path),id='field-'+p.replace(/\W/g,'-');return `<div class="field"><label for="${id}">${safe(label)}${unit?' ('+safe(unit)+')':''}</label><div class="slider-row"><input type="range" aria-label="${safe(label)}" data-path="${p}" min="${min}" max="${max}" step="${step}" value="${value}"><input id="${id}" type="number" data-path="${p}" min="${min}" max="${max}" step="${step}" value="${value}"></div></div>`;}
